const express = require('express');
const app = express();

// Lazily create a Postgres pool from standard PG* env vars / DATABASE_URL.
// Kept lazy so the module can be required in environments without `pg`
// installed (e.g. existing unit tests) without crashing at import time.
let _pool = null;
function getPool() {
  if (_pool !== null) return _pool;
  try {
    const { Pool } = require('pg');
    _pool = new Pool(); // reads PG* / DATABASE_URL from the environment
  } catch (err) {
    _pool = false; // sentinel: pg unavailable
  }
  return _pool;
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

