const express = require('express');
const app = express();

// Lazy-loaded DB client. In a real service this would be a shared pg Pool
// imported from a db module; we resolve it here so tests can inject a mock.
function getDb() {
  if (app.locals.db) return app.locals.db;
  // Default: a pg Pool created from standard PG* env vars.
  // Wrapped in a try so the module still loads in environments without `pg`.
  try {
    const { Pool } = require('pg');
    app.locals.db = new Pool();
    return app.locals.db;
  } catch (err) {
    return null;
  }
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Kubernetes readiness probe: 200 only when Postgres is reachable.
app.get('/healthz', async (req, res) => {
  const db = getDb();
  if (!db) {
    return res.status(503).json({ db: 'unavailable' });
  }
  try {
    await db.query('SELECT 1');
    return res.status(200).json({ db: 'ok' });
  } catch (err) {
    return res.status(503).json({ db: 'error' });
